public class InvocationMatcher_captureArgumentsFrom_TriageGen0Test {

    private Invocation invocation;
    private List<Matcher> matchers;
    private InvocationMatcher invocationMatcher;

    // Mocking CapturesArguments interface/class behavior
    private static class CapturesArguments implements Matcher {
        Object captured;
        @Override
        public boolean matches(Object argument) { return true; }
        public void captureFrom(Object argument) { this.captured = argument; }
    }

    @Before
    public void setUp() {
        invocation = org.mockito.Mockito.mock(Invocation.class);
        matchers = new ArrayList<>();
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarargs_WithCapturesArguments() {
        Method method = String.class.getMethod("length");
        org.mockito.Mockito.when(invocation.getMethod()).thenReturn(method);
        org.mockito.Mockito.when(invocation.getRawArguments()).thenReturn(new Object[]{});

        CapturesArguments capturer = new CapturesArguments();
        matchers.add(capturer);
        matchers.add(NULL_MATCHER); // Non-capturing matcher

        invocationMatcher = new InvocationMatcher(invocation, matchers);

        org.mockito.Mockito.when(invocation.getArgumentAt(0, Object.class)).thenReturn("hello");

        invocationMatcher.captureArgumentsFrom(invocation);

        org.junit.Assert.assertEquals("hello", capturer.captured);
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarargs_WithoutCapturesArguments() {
        Method method = String.class.getMethod("length");
        org.mockito.Mockito.when(invocation.getMethod()).thenReturn(method);
        org.mockito.Mockito.when(invocation.getRawArguments()).thenReturn(new Object[]{});

        matchers.add(NULL_MATCHER);

        invocationMatcher = new InvocationMatcher(invocation, matchers);
        invocationMatcher.captureArgumentsFrom(invocation);
        // No exception means success
    }

    @Test
    public void testCaptureArgumentsFrom_Varargs_NormalArgsAndVararg() {
        // Method with varargs: String.format(String format, Object... args)
        Method method = String.class.getMethod("format", String.class, Object[].class);
        org.mockito.Mockito.when(invocation.getMethod()).thenReturn(method);

        // Arguments: ["%s %s", "arg1", "arg2"]
        Object[] rawArgs = new Object[]{"%s %s", "arg1", "arg2"};
        org.mockito.Mockito.when(invocation.getRawArguments()).thenReturn(rawArgs);

        CapturesArguments capturer1 = new CapturesArguments();
        CapturesArguments capturer2 = new CapturesArguments();
        CapturesArguments capturerVararg = new CapturesArguments();

        matchers.add(capturer1); // matches "%s %s"
        matchers.add(capturer2); // matches "arg1" (part of vararg array)
        matchers.add(capturerVararg); // matches "arg2" (part of vararg array)

        invocationMatcher = new InvocationMatcher(invocation, matchers);

        // Mock getArgumentAt for non-vararg parts
        org.mockito.Mockito.when(invocation.getArgumentAt(0, Object.class)).thenReturn("%s %s");
        org.mockito.Mockito.when(invocation.getArgumentAt(1, Object.class)).thenReturn("arg1");

        invocationMatcher.captureArgumentsFrom(invocation);

        org.junit.Assert.assertEquals("%s %s", capturer1.captured);
        // For varargs, the code uses invocation.getRawArguments()[position - indexOfVararg]
        // indexOfVararg = 3 - 1 = 2.
        // position 2: captures from rawArgs[2 - 2] = rawArgs[0] -> This logic in the source code seems to 
        // treat the varargs array elements as being indexed from 0 in the rawArgs array relative to the vararg start.
        // Let's verify the actual code logic: 
        // indexOfVararg = length - 1. 
        // Loop 1: 0 to indexOfVararg-1.
        // Loop 2: indexOfVararg to matchers.size(). 
        // captures from rawArgs[position - indexOfVararg].

        // If rawArgs = [A, B, C] and length=3, indexOfVararg=2.
        // Loop 1: position 0, 1.
        // Loop 2: position 2. captures from rawArgs[2-2] = rawArgs[0].

        // This test validates the specific (and perhaps unusual) logic implemented in the provided snippet.
        org.junit.Assert.assertEquals("%s %s", capturerVararg.captured);
    }

